import QRCode from 'qrcode';
const root=document.getElementById('app')!;
const esc=(s:unknown)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const icon=(name:string)=>{const shapes:Record<string,string>={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',screen:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-16-2 20"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.arrow}</svg>`;};
let activeToken:string|undefined;
let deadline=0;
let stopped=false;
const messages:Record<string,string>={provider_login_required:'Sign in to the provider on your phone to continue.',pairing_expired:'This code has expired. Start a new request on the TV.',pairing_already_decided:'This request has already been handled.',code_mismatch:'The codes do not match. Check the code shown on your TV.',session_ended:'This session has ended.',invalid_token:'This access credential is no longer valid.',account_unavailable:'The provider cannot authorize this account.',origin_not_allowed:'Use the same public HTTPS address on both devices.',rate_limited:'Too many requests. Wait a minute, then try again.',invalid_request:'Check the code and request details, then try again.',expired_token:'This QR code has expired. Start again on the TV.'};
class ApiError extends Error{constructor(readonly code:string,readonly status:number){super(messages[code]||'We could not complete this request. Please try again.');}}
async function api(path:string,body?:unknown,token?:string){
 const response=await fetch('/api/temporary/'+path,{method:body===undefined?'GET':'POST',credentials:token?'omit':'same-origin',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(10000)});
 const value=await response.json();if(!response.ok)throw new ApiError(value.error,response.status);return value;
}
function shell(content:string,variant=''){
 const path=location.pathname;
 document.body.dataset.view=variant;
 root.innerHTML=`<header class="site-header"><a class="brand" href="/" aria-label="tempLogin home"><span class="brand-mark">${icon('clock')}</span>temp<span>Login</span></a><nav aria-label="Main navigation">${[['/','Overview'],['/tv','Live demo'],['/guide','Developer guide'],['/temporary-sessions','Sessions']].map(([url,label])=>`<a href="${url}" ${path===url?'aria-current="page"':''}>${label}</a>`).join('')}</nav><span class="release-tag">OPEN SOURCE <span>RC.3</span></span></header><main id="main" class="${variant}" tabindex="-1">${content}</main><footer><a class="brand small-brand" href="/">temp<span>Login</span></a><span>Provider-owned identity. Time-limited access.</span><a href="/guide#readiness">Apache-2.0 · Evaluation release</a></footer>`;
}
const feedback='<div id="feedback" class="feedback" role="status" aria-live="polite"></div>';
const demoBadge='<span class="badge demo-badge"><span class="status-dot"></span>Screen Demo · fictional provider</span>';
const clock=(time:number)=>new Date(time).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'});
const frame=(content:string)=>`<section class="phone-flow"><a class="back-link" href="/tv">← Back to the TV demo</a><div class="panel phone-panel">${content}</div><p class="flow-footnote">${icon('shield')} No tempLogin account. No password sharing.</p></section>`;
function note(text:string){const el=document.getElementById('feedback');if(el)el.textContent=text;}
function error(e:unknown){note(e instanceof ApiError?e.message:'Connection unavailable. Check your network and try again.');}
function click(id:string,run:()=>Promise<void>){document.getElementById(id)?.addEventListener('click',async()=>{const button=document.getElementById(id) as HTMLButtonElement;button.disabled=true;try{await run();}catch(e){error(e);}finally{if(button.isConnected)button.disabled=false;}});}
function end(message:string){activeToken=undefined;stopped=true;shell(frame(`<span class="icon-tile">${icon('shield')}</span><p class="eyebrow">SESSION CLOSED</p><h1>${esc(message)}</h1><p class="muted">This screen has discarded its session credential. Start a new request whenever you need access again.</p><a class="button full" href="/tv">Start a new session ${icon('arrow')}</a>${feedback}`),'flow-page');}
const wait=(ms:number)=>new Promise(resolve=>setTimeout(resolve,ms));
async function loginGate(code:string,mode:{demo:boolean;configured:boolean}){
 if(!mode.configured){shell(frame(`<span class="icon-tile">${icon('code')}</span><p class="eyebrow">PROVIDER SETUP</p><h1>Connect your existing login.</h1><p class="muted">This deployment needs a verified provider identity adapter. The fictional demo login is disabled in production.</p><a class="button full" href="/guide#integration">View integration steps ${icon('arrow')}</a>`),'flow-page');return;}
 shell(frame(`${mode.demo?demoBadge:'<p class="eyebrow">PROVIDER SIGN-IN</p>'}<div class="flow-steps"><span class="current">01 Sign in</span><span>02 Authorize</span><span>03 Connected</span></div><h1>Your account.<br>Your provider.</h1><p class="muted">Use the account you already have with the service. There is no tempLogin registration.</p>${mode.demo?`<div class="identity-preview"><span class="avatar">DG</span><div><strong>Demo Guest</strong><span>Sample Screen Demo account</span></div>${icon('shield')}</div><button id="provider-login" class="full">Continue with demo account ${icon('arrow')}</button><p class="help">This button simulates the provider’s login. It does not connect to a real streaming account or ask for credentials.</p>`:'<div class="notice">Sign in using your provider’s login, then return to this request. The provider implements this navigation as part of its integration.</div>'}${feedback}`),'flow-page');
 click('provider-login',async()=>{await api('demo-login',{});if(code)await approve(code);else location.href='/temporary-sessions';});
}
async function approve(initial?:string){
 const code=(initial||new URLSearchParams(location.search).get('code')||'').trim().toUpperCase();
 if(!code){shell(frame(`<span class="icon-tile">${icon('screen')}</span><p class="eyebrow">CONNECT A SCREEN</p><h1>Enter your TV code.</h1><p class="muted">Find the code beneath the QR on the TV you want to authorize.</p><form id="code-form" class="form-stack"><label for="code">TV verification code</label><input id="code" required maxlength="11" pattern="[A-Z2-9]{5}-[A-Z2-9]{5}" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="ABCDE-FG234"><button class="full">Continue ${icon('arrow')}</button></form>${feedback}`),'flow-page');document.getElementById('code-form')?.addEventListener('submit',e=>{e.preventDefault();location.href='/approve?code='+encodeURIComponent((document.getElementById('code') as HTMLInputElement).value.toUpperCase());});return;}
 const mode=await api('mode');let ctx;
 try{ctx=await api('context?code='+encodeURIComponent(code));}catch(e){if(e instanceof ApiError&&e.status===401)return loginGate(code,mode);throw e;}
 if(ctx.status!=='pending'){shell(frame('<p class="eyebrow">REQUEST COMPLETE</p><h1>Already handled.</h1><p class="muted">This code has already been approved or declined.</p><a class="button full" href="/temporary-sessions">View your sessions</a>'),'flow-page');return;}
 const choices:Array<[number,string]>=[...(mode.demo?[[15,'15 seconds · quick expiry test']] as Array<[number,string]>:[]),[900,'15 minutes'],[1800,'30 minutes'],[3600,'1 hour'],[7200,'2 hours']].filter(([n])=>Number(n)<=ctx.max_duration_seconds) as Array<[number,string]>;
 shell(frame(`${mode.demo?demoBadge:`<p class="eyebrow">${esc(ctx.provider)}</p>`}<div class="flow-steps"><span>01 Sign in</span><span class="current">02 Authorize</span><span>03 Connected</span></div><h1>Allow this TV?</h1><p class="muted">Choose how long this screen can use your account.</p><div class="consent-details"><div><span>Provider account</span><strong>${esc(ctx.account)}</strong></div><div><span>Requested screen</span><strong>${esc(ctx.device_name)}</strong></div></div><p class="help">The device name is self-reported, not hardware-verified.</p><div class="verification-code"><span>MATCH THIS CODE ON YOUR TV</span><strong>${esc(code)}</strong></div><form id="consent" class="form-stack"><div><label for="duration">Access duration</label><select id="duration">${choices.map(([n,label])=>`<option value="${n}" ${n===3600?'selected':''}>${label}</option>`).join('')}</select></div><label class="checkbox"><input type="checkbox" id="match" required><span>This code matches the TV I am using.</span></label><p class="consent-note">Only this temporary session will end. Your other devices stay signed in.</p><button id="approve" class="full">Authorize this TV ${icon('arrow')}</button><button type="button" id="deny" class="text-button full">Decline request</button></form>${feedback}`),'flow-page');
 const decision=async(approved:boolean)=>{const result=await api('decision',{code,matching_code:code,approve:approved,duration_seconds:Number((document.getElementById('duration') as HTMLSelectElement).value)});shell(frame(`<span class="icon-tile ${approved?'success':''}">${icon(approved?'check':'shield')}</span><p class="eyebrow">${approved?'YOU’RE ALL SET':'REQUEST CLOSED'}</p><h1>${approved?'TV authorized.':'Request declined.'}</h1><p class="muted">${approved?'Your TV will connect automatically. This session ends at <strong>'+clock(result.expires_at)+'</strong>. You can end it earlier below.':'No access was granted. You can start another request from the TV.'}</p><a class="button full" href="/temporary-sessions">Manage sessions ${icon('arrow')}</a>`),'flow-page');};
 document.getElementById('consent')?.addEventListener('submit',async e=>{e.preventDefault();const buttons=document.querySelectorAll<HTMLButtonElement>('#consent button');buttons.forEach(b=>b.disabled=true);try{await decision(true);}catch(err){error(err);buttons.forEach(b=>b.disabled=false);}});
 click('deny',()=>decision(false));
}
async function sessions(){
 const mode=await api('mode');let rows;
 try{rows=await api('sessions');}catch(e){if(e instanceof ApiError&&e.status===401)return loginGate('',mode);throw e;}
 const active=rows.filter((s:{revoked:boolean})=>!s.revoked).length;
 shell(`<section class="session-page"><div class="page-heading"><div><p class="eyebrow">YOUR CONTROL CENTER</p><h1>Temporary sessions.</h1><p class="muted">Manage access using your provider identity. No extra account.</p></div><span class="badge">${active} active</span></div><div class="panel sessions-panel">${rows.length?rows.map((s:{id:string;device_name:string;expires_at:number;revoked:boolean})=>`<article class="session-row"><span class="icon-tile compact">${icon('screen')}</span><div class="session-info"><strong>${esc(s.device_name)}</strong><span>${s.revoked?'Access revoked':'Expires at '+clock(s.expires_at)}</span></div><span class="session-state ${s.revoked?'muted-state':''}">${s.revoked?'Ended':'Active'}</span>${s.revoked?'':`<button class="secondary revoke" data-id="${esc(s.id)}">Revoke access</button>`}</article>`).join(''):`<div class="empty"><span class="icon-tile">${icon('screen')}</span><h2>No active sessions.</h2><p class="muted">Authorize a TV to see it here. Expired sessions are no longer listed.</p><a class="button" href="/tv">Try the TV demo ${icon('arrow')}</a></div>`}${feedback}</div><div class="inline-note">${icon('shield')} Revoking a session does not sign out your other devices.</div></section>`);
 document.querySelectorAll<HTMLButtonElement>('.revoke').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api('sessions/'+encodeURIComponent(b.dataset.id!)+'/revoke',{});await sessions();}catch(e){error(e);b.disabled=false;}}));
}
const tvHeading=(right='')=>`<div class="tv-heading"><span class="tv-brand">${icon('screen')} SCREEN DEMO</span><span>${right||'FICTIONAL PROVIDER'}</span></div>`;
async function tv(){
 const mode=await api('mode');if(!mode.configured)return loginGate('',mode);
 shell(`<div class="demo-page"><div class="page-heading"><div><p class="eyebrow">LIVE REFERENCE DEMO</p><h1>A shared screen.<br>A session that ends.</h1></div><a class="subtle-link" href="/guide#test">How to test ${icon('arrow')}</a></div><section class="tv-surface">${tvHeading()}<div class="tv-welcome"><div><span class="dark-icon">${icon('clock')}</span><h2>Make yourself<br>at home. Temporarily.</h2><p>Connect on your phone. Choose a duration.<br>Leave your other devices signed in.</p><div class="tv-benefits"><span>${icon('phone')} No extra app</span><span>${icon('shield')} No password sharing</span></div></div><div class="tv-start"><label for="device-name">Screen name</label><input id="device-name" maxlength="80" value="Living room TV"><button id="start" class="full">Connect with tempLogin ${icon('arrow')}</button><p>Your phone approves the session.<br>This TV never asks for your password.</p>${feedback}</div></div><div class="tv-bottom"><span>POWERED BY TEMPLOGIN</span><span>Provider-owned identity · Time-limited access</span></div></section>${location.hostname==='localhost'||location.hostname==='127.0.0.1'?'<div class="notice local-notice"><strong>Testing on your phone?</strong><span>Run <code>npm run dev:phone</code> and open its public HTTPS link on this screen. A localhost QR cannot reach your computer from your phone.</span><a href="/guide#setup">Setup instructions →</a></div>':''}<p class="demo-caption">Screen Demo simulates a provider account. Pairing, consent, expiry and revocation use the real reference backend.</p></div>`,'wide-page');
 click('start',async()=>{
  const p=await api('pairings',{device_name:(document.getElementById('device-name') as HTMLInputElement).value});
  shell(`<div class="demo-page"><a class="back-link" href="/tv">← Cancel and return</a><section class="tv-surface">${tvHeading('<span class="pulse-dot"></span> WAITING FOR APPROVAL')}<div class="tv-pairing"><div><p class="eyebrow">CONNECT FROM YOUR PHONE</p><h1>Scan. Confirm.<br>Make it yours.</h1><ol class="tv-instructions"><li><span>01</span>Scan the QR with your phone camera.</li><li><span>02</span>Continue with the sample provider account.</li><li><span>03</span>Match the code and choose your duration.</li></ol><p class="tv-small">No phone available? <a id="verification-link" href="${esc(p.verification_uri_complete)}" target="_blank" rel="noopener noreferrer">Open the phone flow in another tab ↗</a></p>${feedback}</div><div class="qr-panel"><canvas id="qr" role="img" aria-label="QR code to authorize this TV"></canvas><span>VERIFY THIS CODE</span><strong class="pair-code">${esc(p.user_code)}</strong><span id="pair-expiry">Code expires in 5:00</span></div></div><div class="tv-bottom"><span>POWERED BY TEMPLOGIN</span><span>Keep this screen open</span></div></section><p class="demo-caption">For a fast check, choose “15 seconds · quick expiry test” on the phone.</p></div>`,'wide-page');
  await QRCode.toCanvas(document.getElementById('qr'),p.verification_uri_complete,{width:240,margin:2,color:{dark:'#151c30',light:'#ffffff'}});
  let interval=p.interval*1000;const until=Date.now()+p.expires_in*1000;
  const displayTimer=setInterval(()=>{const el=document.getElementById('pair-expiry'),seconds=Math.max(0,Math.ceil((until-Date.now())/1000));if(el)el.textContent=`Code expires in ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;},1000);
  try{
   while(!stopped&&Date.now()<until){
    await wait(interval);
    try{const result=await api('token',{device_code:p.device_code});activeToken=result.access_token;deadline=result.expires_at;clearInterval(displayTimer);await connected();return;}
    catch(e){if(e instanceof ApiError&&e.code==='authorization_pending')continue;if(e instanceof ApiError&&e.code==='slow_down'){interval+=5000;continue;}if(e instanceof ApiError&&e.code==='access_denied'){end('Access declined.');return;}throw e;}
   }
   end('This code has expired.');
  }finally{clearInterval(displayTimer);}
 });
}
async function connected(){
 shell(`<div class="demo-page"><section class="tv-surface active-surface">${tvHeading('<span class="pulse-dot"></span> SESSION ACTIVE')}<div class="connected-layout"><div><span class="dark-icon">${icon('check')}</span><p class="eyebrow">TEMPORARY ACCESS GRANTED</p><h1>You’re connected.</h1><p id="provider-title">Verifying provider access…</p><div class="protected-resource"><span>${icon('shield')}</span><div><strong>Protected resource</strong><p>Validated against the session and provider on every request.</p></div><span class="resource-indicator" aria-label="Access is being checked"></span></div><p class="tv-small">This is an authorization demo, not commercial streaming content.</p></div><div class="timer-card"><span>TIME REMAINING</span><strong id="countdown" role="timer" aria-live="off">—</strong><p>Access ends automatically.<br>Other devices stay signed in.</p><button id="logout" class="secondary full">Sign out of this TV</button>${feedback}</div></div><div class="tv-bottom"><span>POWERED BY TEMPLOGIN</span><span>Session credential stays in memory</span></div></section><p class="demo-caption">You can also revoke this session from the phone’s Sessions page.</p></div>`,'wide-page');
 click('logout',async()=>{const token=activeToken;if(!token)return;try{await api('logout',{},token);end('You’re signed out.');}catch{end('Screen disconnected.');note('Server revocation could not be confirmed. Revoke the session from your phone, or wait for its original expiry.');}});
 let nextCheck=0;
 while(activeToken&&!stopped){
  const remaining=deadline-Date.now();if(remaining<=0){end('Your time is up.');return;}
  const el=document.getElementById('countdown');const seconds=Math.ceil(remaining/1000);if(el)el.textContent=`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
  if(Date.now()>=nextCheck){
   try{const content=await api('content',undefined,activeToken);if(stopped)return;const title=document.getElementById('provider-title');if(title)title.textContent=content.provider+' · Authorized session';nextCheck=Date.now()+3000;}
   catch(e){end(e instanceof ApiError&&e.code==='session_ended'?'Session ended.':'Access cannot be verified.');return;}
  }
  await wait(250);
 }
}
function home(){shell(`<section class="hero"><div class="hero-copy"><div class="badge"><span class="status-dot"></span>OPEN SOURCE · PROVIDER-OWNED</div><h1>Sign in for a while.<br><em>Not for good.</em></h1><p class="hero-lead">Temporary access for shared screens. Scan a QR, use your existing provider account, and choose when the session ends.</p><div class="actions"><a class="button" href="/tv">Try the live demo ${icon('arrow')}</a><a class="button secondary" href="/guide">Explore the integration</a></div><p class="hero-note">No tempLogin account. No extra phone app.</p></div><div class="flow-preview" aria-label="Illustration of a TV session authorized for one hour"><div class="preview-top"><span>THE HANDOFF, AT A GLANCE</span><span class="preview-live">FLOW PREVIEW</span></div><div class="preview-screen"><div class="preview-screen-top">${icon('screen')} Living room TV<span class="mini-status">Connected</span></div><div class="preview-clock">01<span>:</span>00<span>:</span>00</div><p>Your account. This screen. One hour.</p><div class="preview-track"><span></span></div><div class="preview-meta"><span>Access granted</span><span>Automatic expiry</span></div></div><div class="preview-phone"><span class="icon-tile compact">${icon('phone')}</span><div><strong>Approved on your phone</strong><span>Existing provider account</span></div><span class="approved-mark">${icon('check')}</span></div><div class="preview-caption">${icon('shield')} Your provider stays in control.</div></div></section><section class="principles"><div><span>01 / CONNECT</span><h2>Scan, don’t type.</h2><p>Move sign-in from the remote to the phone already in your hand.</p></div><div><span>02 / CONSENT</span><h2>Set your own timer.</h2><p>Authorize one screen for a clear duration, with no extra identity to create.</p></div><div><span>03 / EXPIRE</span><h2>Leave the session behind.</h2><p>The provider enforces its deadline. Your other devices stay signed in.</p></div></section><section class="integration-strip"><div><span class="icon-tile">${icon('code')}</span><p class="eyebrow">BUILT FOR YOUR ENGINEERING TEAM</p><h2>Your login.<br>Your infrastructure.</h2><p>Embed the temporary-session module in your backend. Keep your accounts, entitlement rules and content controls.</p><a class="subtle-link" href="/guide#integration">See the three integration points ${icon('arrow')}</a></div><div class="integration-list"><article><span>01</span><div><h3>Connect identity</h3><p>Verify your existing provider session.</p></div></article><article><span>02</span><div><h3>Guard access</h3><p>Check the session before issuing resources.</p></div></article><article><span>03</span><div><h3>Enforce expiry</h3><p>Apply the deadline to your TV app and media.</p></div></article></div></section><section class="evaluation-callout"><span class="icon-tile compact">${icon('shield')}</span><div><h3>A working reference. An honest starting point.</h3><p>The demo uses a fictional provider. No Netflix, Google, YouTube or Disney+ integration or partnership is claimed. <a href="/guide#readiness">What is ready, and what a pilot needs →</a></p></div></section>`);}
function guide(){shell(`<div class="guide-layout"><aside class="guide-nav" aria-label="Guide sections"><p class="eyebrow">DEVELOPER GUIDE</p><a href="#setup">01 · Start locally</a><a href="#test">02 · Test the handoff</a><a href="#integration">03 · Integrate your app</a><a href="#readiness">04 · Plan a pilot</a><a class="button" href="/tv">Open demo ${icon('arrow')}</a></aside><article class="guide-content"><div class="page-heading"><div><p class="eyebrow">FROM FIRST LOOK TO FIRST INTEGRATION</p><h1>Try it.<br>Then make it yours.</h1><p class="muted">A short evaluation path for product, identity and connected-TV teams.</p></div></div><section id="setup"><span class="section-number">01 / SETUP</span><h2>Start with the reference.</h2><p>Use Node.js 24 or later. From the extracted or cloned repository:</p><div class="code-block"><span>TERMINAL</span><pre><code>npm ci
npm run dev</code></pre></div><p>Open <code>http://localhost:3000/tv</code>. Without a phone, open the link below the QR in a second tab. No account credentials are required for Screen Demo.</p><h3>Use a physical phone</h3><p>On macOS, install the optional Cloudflare tunnel, then run the isolated phone demo:</p><div class="code-block"><span>TERMINAL · MACOS</span><pre><code>brew install cloudflared
npm run dev:phone</code></pre></div><p>Open the printed <strong>HTTPS TV link on your computer</strong>, then scan its QR from your phone. Keep the terminal running. The public URL and demo data are temporary; Ctrl+C stops both.</p><div class="notice">Do not scan a QR from an old localhost tab. On a phone, localhost is the phone itself.</div></section><section id="test"><span class="section-number">02 / EVALUATE</span><h2>Know what success looks like.</h2><ol class="guide-checklist"><li><strong>Start on the TV.</strong><span>Choose “Connect with tempLogin”. A QR and matching code appear.</span></li><li><strong>Continue on the phone.</strong><span>Choose “Continue with demo account”. This simulates only the provider’s existing login.</span></li><li><strong>Check the code and approve.</strong><span>Choose “15 seconds · quick expiry test” for a short test, or one hour for the normal flow.</span></li><li><strong>Watch the TV update.</strong><span>“You’re connected” appears with a running countdown and a guarded resource.</span></li><li><strong>Verify expiry or revocation.</strong><span>Wait for the timer, or choose “Manage sessions” on the phone and revoke access. The TV closes the session.</span></li></ol><p>Repeat and decline a request: the TV must remain unauthorized. Use separate browser profiles to test account isolation. The automated suite covers replay and concurrent decisions.</p><div class="code-block"><span>VERIFY THE REPOSITORY</span><pre><code>npm run check
npx playwright install chromium
npm run test:e2e</code></pre></div></section><section id="integration"><span class="section-number">03 / INTEGRATE</span><h2>Three connections to your app.</h2><div class="integration-cards"><article class="panel"><span class="icon-tile compact">${icon('shield')}</span><h3>Your existing identity</h3><p>Implement <code>identity(request)</code> using a verified provider session. Return an immutable subject and recent authentication time. No tempLogin account table is required.</p></article><article class="panel"><span class="icon-tile compact">${icon('code')}</span><h3>Your protected backend</h3><p>Use <code>entitled(subject)</code> for account eligibility and <code>requireSession(request)</code> on resources. Keep the subject and upstream credentials server-side.</p></article><article class="panel"><span class="icon-tile compact">${icon('screen')}</span><h3>Your TV and playback</h3><p>Add QR/polling, then bind TV state, playback URLs and licences to the session deadline. Clear local profile data at exit.</p></article></div><h3>Package the SDK</h3><div class="code-block"><span>FROM THE REPOSITORY ROOT</span><pre><code>npm run build
npm pack ./packages/provider-sdk</code></pre></div><p>The reference targets Node 24, Fastify 5 and PostgreSQL-compatible transactions. Install the generated tarball in your backend; the package is not published to npm.</p><p>Next, read <strong>docs/INTEGRATION.md</strong> for the complete host contract and code example, and <strong>specs/openapi.json</strong> for the HTTP interface. The source package is <strong>packages/provider-sdk</strong>.</p></section><section id="readiness"><span class="section-number">04 / PILOT</span><h2>Clear responsibilities. No hidden promises.</h2><div class="comparison"><div><h3>Included in this reference</h3><ul><li>QR handoff and explicit consent</li><li>Transactional, single-use token exchange</li><li>Server-side expiry and session revocation</li><li>SDK, HTTP contract and automated tests</li></ul></div><div><h3>Your team connects</h3><ul><li>Real login and entitlement</li><li>Your TV client and playback system</li><li>DRM, buffering and offline policies</li><li>Deployment, security review and hardware testing</li></ul></div></div><p>The demo validates authorization, not physical playback cutoff. Delivered data cannot be recalled. The provider must enforce its deadline throughout the media pipeline.</p><p>This is an Apache-2.0 evaluation release, not a certified production integration. <strong>docs/PILOT-CHECKLIST.md</strong> defines acceptance checks; <strong>docs/VALIDATION.md</strong> records the tests actually run.</p><a class="button" href="/tv">Try the flow now ${icon('arrow')}</a></section></article></div>`);requestAnimationFrame(()=>{if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView();});}
